import type { AutogeneratedInsertableWorkOrder, AutogeneratedWorkOrder } from './autogenerated/autogenerated_work_order.d.ts'
import type { Temporal } from '@js-temporal/polyfill'

type WorkOrderSchedule =
	| { day_order: bigint, start_time: null }
	| { day_order: null, start_time: Temporal.PlainTime }

declare global {
	type DbInsertableWorkOrder = Omit<AutogeneratedInsertableWorkOrder, 'day_order' | 'start_time'> & WorkOrderSchedule
	type DbWorkOrder = Omit<AutogeneratedWorkOrder, 'day_order' | 'start_time'> & WorkOrderSchedule
}
